-- Fictional content for the disposable template preview.
-- Posts table generated from the built-in content type; normal installs still use runtime schema sync.
CREATE TABLE "posts" (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), "notes" TEXT, "title" TEXT, "slug" TEXT, "status" TEXT NOT NULL DEFAULT 'draft', "description" TEXT, "content" TEXT DEFAULT '{"type":"doc","content":[]}', "image_url" TEXT, "featured" INTEGER DEFAULT 0, "category" TEXT, "author" TEXT, "post_date" TEXT);
